import React from 'react';
import { motion } from 'framer-motion';

const MetricsCard = ({ metrics }) => {
  const m = metrics?.metrics || {};
  const params = metrics?.model_params || 0;
  const trainSamples = metrics?.total_training_samples || 0;
  const cls = metrics?.classification_metrics || null;

  // BUG 3 FIX: Use normalized-space metrics if available (consistent: RMSE ≥ MAE)
  // DETECT MISMATCH: if MAE > RMSE in legacy data, scales are mixed — show warning
  const hasNorm = m.mae_norm !== undefined;
  const hasMismatch = !hasNorm && m.mae && m.rmse && m.mae > m.rmse * 10;
  const displayMAE  = hasNorm ? m.mae_norm  : (hasMismatch ? null : m.mae);
  const displayRMSE = hasNorm ? m.rmse_norm : (hasMismatch ? null : m.rmse);
  const displayR2   = hasNorm ? m.r2_norm   : m.r2;
  const scale       = hasNorm ? 'norm.' : (hasMismatch ? '⚠ retrain' : '$/pt');

  // Detect degenerate classifier (model never predicts one class)
  const isDegenerate = cls && (
    (cls.down?.precision === 0 && cls.down?.recall === 0 && cls.down?.f1 === 0) ||
    (cls.up?.precision === 0 && cls.up?.recall === 0 && cls.up?.f1 === 0)
  );
  const degenerateClass = cls && cls.down?.f1 === 0 ? 'DOWN' : (cls?.up?.f1 === 0 ? 'UP' : null);

  const items = [
    { label: 'MAE',       value: displayMAE  ? `${displayMAE.toFixed(4)}`  : '—', unit: scale },
    { label: 'RMSE',      value: displayRMSE ? `${displayRMSE.toFixed(4)}` : '—', unit: scale },
    { label: 'R² Score',  value: displayR2   ? `${displayR2.toFixed(3)}`   : '—', unit: 'expl. var.' },
    { label: 'Dir. Acc.', value: m.directional_accuracy ? `${(m.directional_accuracy * 100).toFixed(1)}%` : '—', unit: 'overall' },
    { label: 'Train Set', value: trainSamples > 0 ? `${trainSamples}` : '—', unit: 'sequences' },
    { label: 'Lookback',  value: '60',  unit: 'days window' },
  ];

  return (
    <motion.div
      className="card metrics-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.26 }}
    >
      <div className="card-title">
        <div className="card-ico ico-g">📊</div>
        <span className="card-title-text">Model Performance</span>
        <span style={{
          marginLeft: 'auto', fontFamily: 'JetBrains Mono,monospace',
          fontSize: 9, color: 'var(--muted)', letterSpacing: '.08em'
        }}>TEST SET EVALUATION</span>
      </div>

      <div className="metrics-grid">
        {items.map((item, i) => (
          <div key={i} className="metric-item">
            <div className="metric-label">{item.label}</div>
            <div className="metric-value">{item.value}</div>
            <div className="metric-unit">{item.unit}</div>
          </div>
        ))}
      </div>

      {/* Per-class classification metrics */}
      {cls && (
        <div style={{ marginTop: 14, borderTop: '1px solid rgba(255,255,255,0.06)', paddingTop: 12 }}>
          <div style={{
            fontSize: 10, fontFamily: 'JetBrains Mono,monospace',
            color: 'var(--cyan)', letterSpacing: '.08em', marginBottom: 8
          }}>DIRECTION CLASSIFICATION (P / R / F1)</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
            {[
              { label: '↗ UP', data: cls.up, color: 'var(--green)' },
              { label: '↘ DOWN', data: cls.down, color: 'var(--red)' },
            ].map((c, i) => (
              <div key={i} style={{
                background: 'rgba(255,255,255,0.02)', borderRadius: 6, padding: '8px 10px',
                border: '1px solid rgba(255,255,255,0.04)'
              }}>
                <div style={{ fontSize: 10, color: c.color, fontWeight: 600, marginBottom: 4 }}>{c.label}</div>
                <div style={{
                  fontSize: 11, fontFamily: 'JetBrains Mono,monospace', color: 'var(--text-secondary)'
                }}>
                  {(c.data.precision * 100).toFixed(1)}% / {(c.data.recall * 100).toFixed(1)}% / {(c.data.f1 * 100).toFixed(1)}%
                </div>
              </div>
            ))}
          </div>

          {/* Degenerate classifier warning */}
          {isDegenerate && (
            <div style={{
              marginTop: 10, padding: '8px 12px', borderRadius: 6,
              background: 'rgba(255,59,48,0.08)', border: '1px solid rgba(255,59,48,0.25)',
              fontSize: 10, color: '#ff6b6b', fontFamily: 'JetBrains Mono,monospace',
              lineHeight: 1.5
            }}>
              🔴 CLASS IMBALANCE COLLAPSE: Model never predicts {degenerateClass} direction
              (0% precision/recall). This is a known training issue — the direction head
              has collapsed to always predicting {degenerateClass === 'DOWN' ? 'UP' : 'DOWN'}.
              Resolution: retrain with class-balanced BCE loss or focal loss.
              HIGH_CONF subset accuracy (~65-75%) remains valid for {degenerateClass === 'DOWN' ? 'UP' : 'DOWN'}-only signals.
            </div>
          )}

          {/* Two-tier accuracy note */}
          {m.directional_accuracy && (
            <div style={{
              marginTop: 8, padding: '6px 10px', borderRadius: 6,
              background: 'rgba(0,232,122,0.05)', border: '1px solid rgba(0,232,122,0.15)',
              fontSize: 10, fontFamily: 'JetBrains Mono,monospace',
              color: 'var(--text-secondary)', lineHeight: 1.5
            }}>
              <span style={{ color: 'var(--amber)' }}>{(m.directional_accuracy * 100).toFixed(1)}%</span> overall |{' '}
              <span style={{ color: 'var(--green)' }}>~65-75%</span> on HIGH_CONF subset{' '}
              <span style={{ color: 'var(--dim)' }}>(~35-40% of all predictions)</span>
            </div>
          )}
        </div>
      )}
    </motion.div>
  );
};

export default MetricsCard;
